import type { Metadata } from "next";
import { withAbsoluteSiteUrls } from "@/lib/absolute-site-metadata";
import { fitDescription } from "@/lib/seo/metadata";

/** Share image for every docs page (generated by ./opengraph-image.tsx). */
export const DOCS_OG_IMAGE = "/docs/opengraph-image";

/**
 * Metadata for one docs page: canonical URL, an article-typed Open Graph card
 * with the docs share image, and the Twitter card. A page's own `openGraph`
 * replaces the layout's wholesale in Next, so each page has to carry the type
 * and image itself — without them the docs shipped no og:type or og:image.
 */
export async function docsMetadata(path: string, title: string, fullDescription: string): Promise<Metadata> {
  const description = fitDescription(fullDescription);
  const fullTitle = `${title} | basefyio Docs`;
  return withAbsoluteSiteUrls(path, {
    title,
    description,
    openGraph: {
      type: "article",
      siteName: "basefyio",
      title: fullTitle,
      description,
      images: [{ url: DOCS_OG_IMAGE, width: 1200, height: 630, alt: "basefyio Docs" }],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [DOCS_OG_IMAGE],
    },
  });
}
